// src/components/SkillsCarousel.jsx
import React, { useState } from 'react';
import { motion } from 'framer-motion';

const skills = [
  'Adobe Creative Suite', 'Community Outreach',
  'Convolutional Neural Networks', 'Educational Services',
  'Java', 'Linux', 'Mentorship',
  'Robotics', 'Team Management',
  'Technical Leadership', 'Web Design'
];

export default function SkillsCarousel({ theme }) {
  // show 4 per “page”
  const pageSize = 4;
  const maxPage = Math.ceil(skills.length / pageSize) - 1;
  const [page, setPage] = useState(0);

  const prev = () => setPage(p => (p > 0 ? p - 1 : maxPage));
  const next = () => setPage(p => (p < maxPage ? p + 1 : 0));

  return (
    <section id="skills" className="py-12">
      <h2
        className={`
          text-2xl font-bold mb-6
          ${theme === 'dark' ? 'text-yellow-400' : 'text-blue-800'}
        `}
      >
        Technical Skills
      </h2>

      <div className="relative">
        {/* Prev button */}
        <button
          onClick={prev}
          aria-label="Previous skills"
          className={`
            absolute left-0 top-1/2 -translate-y-1/2
            p-2 rounded-full shadow
            focus:outline-none focus:ring
            ${theme === 'dark'
              ? 'bg-yellow-600 text-black'
              : 'bg-blue-600 text-white'}
          `}
        >
          ‹
        </button>

        {/* viewport */}
        <div className="overflow-hidden">
          <motion.div
            className="flex"
            animate={{ x: `-${page * 100}%` }}
            transition={{ type: 'spring', stiffness: 100, damping: 20 }}
          >
            {skills.map((skill, i) => (
              <div
                key={i}
                className="flex-shrink-0 w-1/4 px-2"
              >
                <div
                  className={`
                    py-3 text-center rounded-lg border
                    ${theme === 'dark'
                      ? 'border-yellow-400 text-yellow-200'
                      : 'border-blue-800 text-blue-800'}
                  `}
                >
                  {skill}
                </div>
              </div>
            ))}
          </motion.div>
        </div>

        {/* Next button */}
        <button
          onClick={next}
          aria-label="Next skills"
          className={`
            absolute right-0 top-1/2 -translate-y-1/2
            p-2 rounded-full shadow
            focus:outline-none focus:ring
            ${theme === 'dark'
              ? 'bg-yellow-600 text-black'
              : 'bg-blue-600 text-white'}
          `}
        >
          ›
        </button>
      </div>
    </section>
  );
}
